import{_ as t,c as a,o as s,ae as r}from"./chunks/framework.Cd-3tpCq.js";const c=JSON.parse('{"title":"GDPR Requests (Shop)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/gdpr.md","filePath":"api/workflows/shop/gdpr.md"}'),d={name:"api/workflows/shop/gdpr.md"};function i(o,e,n,p,l,h){return s(),a("div",null,e[0]||(e[0]=[r(`<h1 id="gdpr-requests-shop" tabindex="-1">GDPR Requests (Shop) <a class="header-anchor" href="#gdpr-requests-shop" aria-label="Permalink to &quot;GDPR Requests (Shop)&quot;">​</a></h1><p>A customer raises a data request (delete or update their data), lists and views their own requests, revokes a pending one, or deletes the record. The whole surface is gated by an admin setting — when GDPR is disabled in the admin configuration, every call returns an error.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A valid storefront key (<a href="/api/setup.html">Setup</a>, <a href="/api/authentication.html">Authentication</a>).</li><li>A logged-in customer (Bearer <code>token</code>) — requests are owner-scoped.</li><li>GDPR enabled in the admin configuration. If it is off, every endpoint returns <code>400</code> with a &quot;GDPR is disabled&quot; message.</li></ul><h2 id="dependency-diagram" tabindex="-1">Dependency diagram <a class="header-anchor" href="#dependency-diagram" aria-label="Permalink to &quot;Dependency diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login[Customer login&lt;br/&gt;Bearer token] --&gt; raise[POST raise request&lt;br/&gt;type: delete or update]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  raise --&gt; list[GET list requests]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  list --&gt; view[GET view request]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  view --&gt; act{While pending}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  act --&gt; revoke[POST revoke]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  act --&gt; del[DELETE request]</span></span></code></pre></div><h2 id="ordered-call-table" tabindex="-1">Ordered call table <a class="header-anchor" href="#ordered-call-table" aria-label="Permalink to &quot;Ordered call table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Endpoint</th><th>Depends on</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td>Raise request</td><td><a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">POST raise</a> · <a href="/api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.html">GraphQL</a></td><td>logged-in customer</td><td>Body <code>{ type: delete | update, message }</code> → <code>201</code> pending</td></tr><tr><td>2</td><td>List own requests</td><td><a href="/api/rest-api/shop/gdpr-requests/list-gdpr-requests.html">GET list</a> · <a href="/api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.html">GraphQL</a></td><td>logged-in customer</td><td>Only yours</td></tr><tr><td>3</td><td>View request</td><td><a href="/api/rest-api/shop/gdpr-requests/view-gdpr-request.html">GET view</a> · <a href="/api/graphql-api/shop/gdpr-requests/queries/view-gdpr-request.html">GraphQL</a></td><td>one of your requests</td><td><code>404</code> if not yours</td></tr><tr><td>4</td><td>Revoke</td><td><a href="/api/rest-api/shop/gdpr-requests/revoke-gdpr-request.html">POST revoke</a> · <a href="/api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.html">GraphQL</a></td><td>a pending / processing request</td><td><code>422</code> if already resolved</td></tr><tr><td>5</td><td>Delete record</td><td><a href="/api/rest-api/shop/gdpr-requests/delete-gdpr-request.html">DELETE request</a> · <a href="/api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.html">GraphQL</a></td><td>one of your requests</td><td>Removes the request record</td></tr></tbody></table><blockquote><p><strong>GraphQL equivalents:</strong> <code>gdprRequests</code> / <code>gdprRequest</code> (read) and the <code>createGdprRequest</code> / <code>revokeGdprRequest</code> / <code>deleteGdprRequest</code> mutations. Select <strong>result fields</strong> on the mutation payloads, not <code>id</code> — see <a href="/api/graphql-api/identifiers.html">Identifiers</a>.</p></blockquote><h2 id="end-to-end-sequence" tabindex="-1">End-to-end sequence <a class="header-anchor" href="#end-to-end-sequence" aria-label="Permalink to &quot;End-to-end sequence&quot;">​</a></h2><p>raise (delete or update) → list → view → revoke while still pending, or delete the record.</p><p>Revoke only applies while the request is <code>pending</code> or <code>processing</code>; once the store has resolved it, revoke returns <code>422</code> (see <a href="/api/errors.html">Errors</a>).</p><h2 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h2><p>To change GDPR behavior on the server, see <a href="/api/workflows/customization/">Customization → Shop</a>.</p>`,14)]))}const g=t(d,[["render",i]]);export{c as __pageData,g as default};
